function eraseWithStars(s: string): string {
  const gone = new Array(s.length).fill(false);
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== "*") continue;
    gone[i] = true;
    let pick = -1;
    for (let j = i - 1; j >= 0; j--) {
      if (gone[j] || s[j] === "*") continue;
      if (pick === -1 || s[j] < s[pick]) pick = j; // strict: keeps the rightmost copy
    }
    gone[pick] = true;
  }
  let out = "";
  for (let i = 0; i < s.length; i++) if (!gone[i]) out += s[i];
  return out;
}

