function eraseWithStars(s: string): string {
  const stacks: number[][] = Array.from({ length: 26 }, () => []);
  const gone = new Array(s.length).fill(false);
  for (let i = 0; i < s.length; i++) {
    if (s[i] === "*") {
      gone[i] = true;
      for (let c = 0; c < 26; c++) {
        if (stacks[c].length) { gone[stacks[c].pop()!] = true; break; }
      }
    } else {
      stacks[s.charCodeAt(i) - 97].push(i);
    }
  }
  const out: string[] = [];
  for (let i = 0; i < s.length; i++) if (!gone[i]) out.push(s[i]);
  return out.join("");
}

